import{_ as e,o as i,c as t,a2 as a}from"./chunks/framework.CsFjlSKj.js";const u=JSON.parse('{"title":"Security Context Constraints (SCC)","description":"","frontmatter":{},"headers":[],"relativePath":"openshift/3-security-context-constraints.md","filePath":"openshift/3-security-context-constraints.md"}'),n={name:"openshift/3-security-context-constraints.md"};function o(r,s,c,h,l,p){return i(),t("div",null,[...s[0]||(s[0]=[a(`<h1 id="security-context-constraints-scc" tabindex="-1">Security Context Constraints (SCC) <a class="header-anchor" href="#security-context-constraints-scc" aria-label="Permalink to &quot;Security Context Constraints (SCC)&quot;">​</a></h1><p>One of the most common hurdles for newcomers migrating applications from Vanilla Kubernetes to OpenShift is that <strong>their pods immediately crash with a &quot;Permission Denied&quot; error.</strong></p><p>This happens because of <strong>Security Context Constraints (SCC)</strong>.</p><h2 id="what-is-an-scc" tabindex="-1">What is an SCC? <a class="header-anchor" href="#what-is-an-scc" aria-label="Permalink to &quot;What is an SCC?&quot;">​</a></h2><p>An SCC is an OpenShift-specific admission controller that dictates exactly what a pod is allowed to do.</p><p>By default, OpenShift applies the <code>restricted</code> SCC to all pods. The <code>restricted</code> SCC ensures that:</p><ol><li><strong>The pod cannot run as <code>root</code> (UID 0).</strong> OpenShift will literally force the container to run as a randomly assigned high-number User ID (e.g., UID 1000670000).</li><li><strong>The pod cannot bind to privileged ports</strong> (any port below 1024, such as 80 or 443).</li><li><strong>The pod cannot access the host network or host filesystem.</strong></li></ol><h2 id="resolving-permission-issues" tabindex="-1">Resolving Permission Issues <a class="header-anchor" href="#resolving-permission-issues" aria-label="Permalink to &quot;Resolving Permission Issues&quot;">​</a></h2><p>If your container image has hardcoded assumptions that it will run as <code>root</code> (like trying to write to <code>/var/run</code> or binding to port 80), it will fail to start in OpenShift.</p><h3 id="option-1-fix-the-container-image-best-practice" tabindex="-1">Option 1: Fix the Container Image (Best Practice) <a class="header-anchor" href="#option-1-fix-the-container-image-best-practice" aria-label="Permalink to &quot;Option 1: Fix the Container Image (Best Practice)&quot;">​</a></h3><p>The true cloud-native solution is to rebuild your container image so that it does not require root. Use high ports (e.g., 8080 instead of 80) and write logs to <code>stdout</code> or directories where any user has write access (like <code>/tmp</code>).</p><h3 id="option-2-grant-the-pod-access-to-the-anyuid-scc" tabindex="-1">Option 2: Grant the Pod Access to the <code>anyuid</code> SCC <a class="header-anchor" href="#option-2-grant-the-pod-access-to-the-anyuid-scc" aria-label="Permalink to &quot;Option 2: Grant the Pod Access to the \`anyuid\` SCC&quot;">​</a></h3><p>If you are running a third-party image (like an older version of Nginx or PostgreSQL) and cannot change the Dockerfile to run as non-root, you can bypass the restriction by granting the pod&#39;s <strong>ServiceAccount</strong> access to the <code>anyuid</code> SCC.</p><p>The <code>anyuid</code> SCC allows a container to run as the User ID specified in its Dockerfile (including <code>root</code>).</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 1. Create a dedicated ServiceAccount in your project</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">oc</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> create</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> serviceaccount</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my-app-sa</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 2. Grant the &#39;anyuid&#39; SCC to the ServiceAccount (Requires cluster-admin)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">oc</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> adm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> policy</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add-scc-to-user</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> anyuid</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -z</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my-app-sa</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 3. Update your Deployment to use the ServiceAccount</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">oc</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> set</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> serviceaccount</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> deployment/my-app</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my-app-sa</span></span></code></pre></div><p><em>(Note: The <code>-z</code> flag targets a ServiceAccount in the current namespace, rather than a normal human user).</em></p><h2 id="highly-privileged-pods" tabindex="-1">Highly Privileged Pods <a class="header-anchor" href="#highly-privileged-pods" aria-label="Permalink to &quot;Highly Privileged Pods&quot;">​</a></h2><p>Sometimes you need to run infrastructure-level agents (like logging collectors or security scanners) that require full access to the underlying worker node&#39;s host paths or network.</p><p>For these pods, you must grant the <code>privileged</code> SCC.</p><div class="caution custom-block github-alert"><p class="custom-block-title">CAUTION</p><p>The <code>privileged</code> SCC effectively grants the container root access to the physical host machine. Never grant this to standard application workloads.</p></div><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Grant the &#39;privileged&#39; SCC to a daemonset&#39;s ServiceAccount</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">oc</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> adm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> policy</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add-scc-to-user</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> privileged</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -z</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> logging-sa</span></span></code></pre></div>`,21)])])}const g=e(n,[["render",o]]);export{u as __pageData,g as default};
